package com.cqsynet.swifi.db;

import android.content.Context;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;

public class StatisticsDBHelper extends SQLiteOpenHelper {

	// 统计数据库名
	public static final String DATABASE_NAME = "statistics.db";
	// 统计数据库版本
	private final static int DATABASE_VERSION = 5;

	// 统计数据表名
	public static final String TABLE = "statisticsCache";

	// 统计数据字段
	public static final String COL_ID = "id";
	public static final String COL_TYPE = "type";
	public static final String COL_VALUE = "value";
	public static final String COL_COUNT = "count";
	public static final String COL_START_TIME = "startTime";
	public static final String COL_END_TIME = "endTime";


	// 创建统计数据表的语句
	public static final String CREATE_TABLE_STATISTICS = "CREATE TABLE IF NOT EXISTS " + TABLE + "("
			+ COL_ID + " INTEGER PRIMARY KEY AUTOINCREMENT,"
			+ COL_TYPE + " TEXT,"
			+ COL_VALUE + " TEXT,"
			+ COL_COUNT + " TEXT,"
			+ COL_START_TIME + " TEXT,"
			+ COL_END_TIME + " TEXT)";

	public static final String DROP_TABLE_STATISTICS = "DROP TABLE IF EXISTS " + TABLE;

	public StatisticsDBHelper(Context context) {
		super(context, DATABASE_NAME, null, DATABASE_VERSION);
	}

	@Override
	public void onCreate(SQLiteDatabase db) {
		createTable(db);
	}

	@Override
	public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
		db.execSQL(DROP_TABLE_STATISTICS);
		createTable(db);
	}

	public void createTable(SQLiteDatabase db) {
		db.execSQL(CREATE_TABLE_STATISTICS);
	}
}

package cs.tjuscs.st;

import static org.junit.Assert.assertEquals;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import org.junit.Before;
import org.junit.Test;

import cn.tjuscs.st.Prime;

public class testPrime {
    Prime prime;
    ByteArrayOutputStream baos;

    @Before
    public void setUp() throws Exception {
        prime = new Prime();
        baos = new ByteArrayOutputStream();
        System.setOut(new PrintStream(baos));
    }

    @Test
    public void testPrintPrimes() {
        String outcome = new String("Prime: 2\r\nPrime: 3\r\nPrime: 5\r\nPrime: 7\r\nPrime: 11\r\n");
        prime.printPrimes(5);
        assertEquals(outcome, baos.toString()); 
    }

}

package es.uvigo.esei.daa.services.pojo;
import java.io.Serializable;

import es.uvigo.esei.daa.entities.Location;


public class LocationPojo implements Serializable {

	private static final long serialVersionUID = 1L;

	private int id;
	private double longitude;
	private double latitude;

	public LocationPojo(){

	}

	public LocationPojo(Location loc){
		id = loc.getId();
		longitude = loc.getLongitude();
		latitude = loc.getLatitude();
	}

	public double getLongitude() {
		return longitude;
	}

	public void setLongitude(double x) {
		this.longitude = x;
	}

	public double getLatitude() {
		return latitude;
	}

	public void setLatitude(double y) {
		this.latitude = y;
	}

	public int getId() {
		return id;
	}

	public void setId(int id) {
		this.id = id;
	}

}

